66: impl Provider {
67:     pub fn url_for_path(&self, path: &str) -> String {
68:         let base = self.base_url.trim_end_matches('/');
69:         let path = path.trim_start_matches('/');
70:         let mut url = if path.is_empty() {
71:             base.to_string()
72:         } else {
73:             format!("{base}/{path}")
74:         };
75: 
76:         if let Some(params) = &self.query_params
77:             && !params.is_empty()
78:         {
79:             let qs = params
80:                 .iter()
81:                 .map(|(k, v)| format!("{k}={v}"))
82:                 .collect::<Vec<_>>()
83:                 .join("&");
84:             url.push('?');
85:             url.push_str(&qs);
86:         }
87: 
88:         url
89:     }
90: 
91:     pub fn build_request(&self, method: Method, path: &str) -> Request {
92:         Request {
93:             method,
94:             url: self.url_for_path(path),
95:             headers: self.headers.clone(),
96:             body: None,
97:             compression: RequestCompression::None,
98:             timeout: None,
99:         }
100:     }
