102:     pub fn websocket_url_for_path(&self, path: &str) -> Result<Url, url::ParseError> {
103:         let mut url = Url::parse(&self.url_for_path(path))?;
104: 
105:         let scheme = match url.scheme() {
106:             "http" => "ws",
107:             "https" => "wss",
108:             "ws" | "wss" => return Ok(url),
109:             _ => return Ok(url),
110:         };
111:         let _ = url.set_scheme(scheme);
112:         Ok(url)
113:     }
114: }
