126: fn matches_azure_responses_base_url(base_url: &str) -> bool {
127:     let base_url = base_url.to_ascii_lowercase();
128:     const AZURE_MARKERS: [&str; 6] = [
129:         "openai.azure.",
130:         "cognitiveservices.azure.",
131:         "aoai.azure.",
132:         "azure-api.",
133:         "azurefd.",
134:         "windows.net/openai",
135:     ];
136:     AZURE_MARKERS.iter().any(|marker| base_url.contains(marker))
137: }
