131:         return Err(OpenAiFileError::FileTooLarge {
132:             file_name,
133:             size_bytes: file_size_bytes,
134:             limit_bytes: OPENAI_FILE_UPLOAD_LIMIT_BYTES,
135:         });
136:     }
137: 
138:     let create_url = format!("{}/files", base_url.trim_end_matches('/'));
139:     let create_request = serde_json::json!({
140:         "file_name": file_name.as_str(),
141:         "file_size": file_size_bytes,
142:         "use_case": OPENAI_FILE_USE_CASE,
143:     });
144:     let request = authorized_request(client_pool, auth, Method::POST, &create_url);
145:     let create_request = match hosted_upload {
146:         Some(context) => serde_json::json!({
147:             "file_name": file_name.as_str(),
148:             "file_size": file_size_bytes,
149:             "use_case": OPENAI_FILE_USE_CASE,
150:             "codex_connector_id": context.connector_id,
151:             "codex_action_name": context.action_name,
152:             "codex_model": context.model,
153:         }),
154:         None => create_request,
155:     };
156:     let create_response = request
157:         .json(&create_request)
158:         .send()
159:         .await
160:         .map_err(|source| OpenAiFileError::Request {
161:             url: create_url.clone(),
162:             source,
163:         })?;
164:     let create_status = create_response.status();
