221:                 elapsed_ms,
222:                 error_kind,
223:                 azure_client_request_id: azure_client_request_id.clone(),
224:                 source: source.without_url(),
225:             }
226:         })?;
227:     let upload_status = upload_response.status();
228:     let cloudflare_ray_id = upload_response_header(&upload_response, "cf-ray");
229:     let azure_request_id = upload_response_header(&upload_response, "x-ms-request-id");
