366:         client_metadata.insert(
367:             WS_REQUEST_HEADER_TRACEPARENT_CLIENT_METADATA_KEY.to_string(),
368:             traceparent.to_string(),
369:         );
370:     }
371:     if let Some(tracestate) = trace.and_then(|trace| trace.tracestate.as_deref()) {
372:         client_metadata.insert(
373:             WS_REQUEST_HEADER_TRACESTATE_CLIENT_METADATA_KEY.to_string(),
374:             tracestate.to_string(),
375:         );
376:     }
377: 
378:     (!client_metadata.is_empty()).then_some(client_metadata)
379: }
